    bg = vals.most_common(1)[0][0]
    cells = [(r,c) for r in range(R) for c in range(C) if g[r][c]!=bg]
    if not cells: return g
    r0=min(r for r,c in cells); r1=max(r for r,c in cells)
    c0=min(c for r,c in cells); c1=max(c for r,c in cells)
    out=[row[:] for row in g]
    # 1) fill background cells on the bbox perimeter
    for c in range(c0,c1+1):
        for r in (r0,r1):
            if g[r][c]==bg: out[r][c]=2
    for r in range(r0,r1+1):
        for c in (c0,c1):
            if g[r][c]==bg: out[r][c]=2
    # 2) rows with >=4 marks: fill whole span between first/last mark;
    #    rows with fewer marks: fill only small gaps (<=2) between consecutive marks
    for r in range(r0,r1+1):
        m=[c for c in range(c0,c1+1) if g[r][c]!=bg]
        if len(m)>=4:
            for c in range(m[0],m[-1]+1):
                if g[r][c]==bg: out[r][c]=2
        else:
            for a,b in zip(m,m[1:]):
                if 0 < b-a-1 <= 2:
                    for c in range(a+1,b):
                        if g[r][c]==bg: out[r][c]=2
    return out
'''
